def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        if history[0][1] == 'D':
            return 'D'
        return 'C'
    my_last, opp_last = history[-1]
    opp_defections = sum(1 for _, o in history if o == 'D')
    # Defect against a confirmed defector
    if opp_defections >= 3 and opp_defections >= n // 2:
        return 'D'
    # Tit-for-two-tats: defect if opponent defected in the last two rounds
    if history[-1][1] == 'D' and history[-2][1] == 'D':
        return 'D'
    # Endgame
    remaining = 100 - n
    if remaining <= 1:
        return 'D'
    if remaining == 2:
        recent_def = False
        start = max(0, n - 10)
        for i in range(start, n):
            if history[i][1] == 'D':
                recent_def = True
                break
        if recent_def or opp_defections >= 2:
            return 'D'
        return 'C'
    # Continued punishment if both defected last round
    if opp_last == 'D' and my_last == 'D':
        if rng.random() < 0.7:
            return 'D'
    return 'C'
